package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen0Test {

    @Test
    public void testCreatePath_IsAttribute() {
        // Arrange
        JXPathContext context = mock(JXPathContext.class);
        NodePointer parentPointer = mock(NodePointer.class);
        NodePointer newParent = mock(NodePointer.class);
        NodePointer attributePointer = mock(NodePointer.class);
        QName name = new QName("testAttr");

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(parentPointer));

        doReturn(true).when(nullPropertyPointer).isAttribute();
        doReturn(name).when(nullPropertyPointer).getName();
        when(parentPointer.createPath(context)).thenReturn(newParent);
        when(newParent.createAttribute(context, name)).thenReturn(attributePointer);

        // Act
        NodePointer result = nullPropertyPointer.createPath(context);

        // Assert
        verify(parentPointer).createPath(context);
        verify(newParent).createAttribute(context, name);
        assert result == attributePointer;
    }

    @Test
    public void testCreatePath_IsNotAttribute_NewParentIsPropertyOwnerPointer() {
        // Arrange
        JXPathContext context = mock(JXPathContext.class);
        NodePointer parentPointer = mock(NodePointer.class);
        NodePointer propertyOwnerPointer = mock(PropertyOwnerPointer.class);
        NodePointer propertyPointer = mock(NodePointer.class);
        NodePointer finalChildPointer = mock(NodePointer.class);
        QName name = new QName("testProp");
        int index = 0;

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(parentPointer));

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(name).when(nullPropertyPointer).getName();
        doReturn(index).when(nullPropertyPointer).getIndex();

        when(parentPointer.createPath(context)).thenReturn(propertyOwnerPointer);
        when(propertyOwnerPointer.getPropertyPointer()).thenReturn(propertyPointer);
        when(propertyPointer.createChild(context, name, index)).thenReturn(finalChildPointer);

        // Act
        NodePointer result = nullPropertyPointer.createPath(context);

        // Assert
        verify(propertyOwnerPointer).getPropertyPointer();
        verify(propertyPointer).createChild(context, name, index);
        assert result == finalChildPointer;
    }

    @Test
    public void testCreatePath_IsNotAttribute_NewParentIsNotPropertyOwnerPointer() {
        // Arrange
        JXPathContext context = mock(JXPathContext.class);
        NodePointer parentPointer = mock(NodePointer.class);
        NodePointer otherPointer = mock(NodePointer.class); // e.g., DOMNodePointer
        NodePointer finalChildPointer = mock(NodePointer.class);
        QName name = new QName("testChild");
        int index = 5;

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(parentPointer));

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(name).when(nullPropertyPointer).getName();
        doReturn(index).when(nullPropertyPointer).getIndex();

        when(parentPointer.createPath(context)).thenReturn(otherPointer);
        when(otherPointer.createChild(context, name, index)).thenReturn(finalChildPointer);

        // Act
        NodePointer result = nullPropertyPointer.createPath(context);

        // Assert
        // Verify it didn't try to cast to PropertyOwnerPointer/getPropertyPointer
        verify(otherPointer).createChild(context, name, index);
        assert result == finalChildPointer;
    }
}
